  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    node_to_idx = {node: i for i, node in enumerate(nodes)}
    n = len(nodes)
    edges = []
    for v1, v2, d in distances:
        w = max(core[v1], core[v2], d)
        a, b = (v1, v2) if v1 < v2 else (v2, v1)
        edges.append((w, a, b))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst = []
    total = 0.0
    for w, a, b in edges:
        if len(mst) == n - 1:
            break
        ia, ib = node_to_idx[a], node_to_idx[b]
        if union(ia, ib):
            mst.append([a, b, w])
            total += w
    if len(mst) != n - 1:
        raise ValueError('Graph is disconnected')
    return {'mst_edges': mst, 'total_weight': total}"
}
